427:   private void validate() {
428:     try {
429:       Objects.requireNonNull(clientId, String.format(INVALID_ARGUMENT_MSG, "client id"));
430:       if (entraConfigurationProvided()) {
431:         // loading the certificate from the provided path to ensure it exists and is valid
432:         final KeyStore keyStore = KeyStore.getInstance("PKCS12");
433:         keyStore.load(
434:             Files.newInputStream(Paths.get(sslClientCertPath.toAbsolutePath().toString())),
435:             sslClientCertPassword.toCharArray());
436:       } else {
437:         Objects.requireNonNull(clientSecret, String.format(INVALID_ARGUMENT_MSG, "client secret"));
438:       }
439:       Objects.requireNonNull(audience, String.format(INVALID_ARGUMENT_MSG, "audience"));
440:       Objects.requireNonNull(
441:           authorizationServerUrl, String.format(INVALID_ARGUMENT_MSG, "authorization server URL"));
442: 
443:       authorizationServer = new URL(authorizationServerUrl);
444: 
445:       if (keystorePath != null && !keystorePath.toFile().exists()) {
446:         throw new IllegalArgumentException("Keystore path does not exist: " + keystorePath);
447:       }
448: 
449:       if (truststorePath != null && !truststorePath.toFile().exists()) {
450:         throw new IllegalArgumentException("Truststore path does not exist: " + keystorePath);
451:       }
452: 
453:       credentialsCache = new File(credentialsCachePath);
454: 
455:       if (credentialsCache.isDirectory()) {
456:         throw new IllegalArgumentException(
457:             "Expected specified credentials cache to be a file but found directory instead.");
458:       }
459:       validateTimeout(connectTimeout, "ConnectTimeout");
460:       validateTimeout(readTimeout, "ReadTimeout");
461:     } catch (final NullPointerException
462:                    | IOException
463:                    | KeyStoreException
464:                    | NoSuchAlgorithmException
465:                    | CertificateException e) {
466:       throw new IllegalArgumentException(e);
467:     }
468:   }
469: 
470:   private void validateTimeout(final Duration timeout, final String timeoutName) {
471:     if (timeout.isZero() || timeout.isNegative() || timeout.toMillis() > Integer.MAX_VALUE) {
472:       throw new IllegalArgumentException(
473:           String.format(
474:               "%s timeout is %s milliseconds, expected timeout to be a positive number of milliseconds smaller than %s.",
475:               timeoutName, timeout.toMillis(), Integer.MAX_VALUE));
476:     }
477:   }
478: }
