496:   private static String encode(final String param) {
497:     try {
498:       return URLEncoder.encode(param, StandardCharsets.UTF_8.name());
499:     } catch (final UnsupportedEncodingException e) {
500:       throw new UncheckedIOException("Failed while encoding OAuth request parameters: ", e);
501:     }
502:   }
