93:   @Override
94:   public void processRecord(final TypedRecord<UserTaskRecord> command) {
95:     final UserTaskIntent intentToWrite = (UserTaskIntent) command.getIntent();
96:     switch (intentToWrite) {
97:       case CREATE, ASSIGN, CLAIM, UPDATE, COMPLETE, CANCEL ->
98:           processOperationCommand(command, intentToWrite);
99:       case COMPLETE_TASK_LISTENER -> processCompleteTaskListener(command);
100:       case DENY_TASK_LISTENER -> processDenyTaskListener(command);
101:       default ->
102:           throw new UnsupportedOperationException("Unexpected user task intent: " + intentToWrite);
103:     }
104:   }
