151:     final var persistedRecord = userTaskState.getUserTask(command.getKey());
152: 
153:     switch (lifecycleState) {
154:       case COMPLETING ->
155:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.COMPLETION_DENIED);
156:       case ASSIGNING, CLAIMING ->
157:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.ASSIGNMENT_DENIED);
158:       case UPDATING ->
159:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.UPDATE_DENIED);
