228:   private void storeUserTaskRecordRequestMetadata(final TypedRecord<UserTaskRecord> command) {
229:     if (!command.hasRequestMetadata()) {
230:       return;
231:     }
232: 
233:     final var metadata =
234:         new UserTaskTransitionTriggerRequestMetadata()
235:             .setIntent(command.getIntent())
236:             .setTriggerType(ValueType.USER_TASK)
237:             .setRequestId(command.getRequestId())
238:             .setRequestStreamId(command.getRequestStreamId());
239:     userTaskState.storeRecordRequestMetadata(command.getValue().getUserTaskKey(), metadata);
240:   }
