242:   private void handleCommandRejection(
243:       final TypedRecord<UserTaskRecord> command, final Rejection rejection) {
244:     rejectionWriter.appendRejection(command, rejection.type(), rejection.reason());
245:     responseWriter.writeRejectionOnCommand(command, rejection.type(), rejection.reason());
246:   }
