117:     if (command.getValue().hasChangedAttributes()) {
118:       intermediateUserTaskRecord.wrapChangedAttributesIfValueChanged(command.getValue());
119: 
120:       if (intermediateUserTaskRecord.hasChangedAttributes()) {
121:         stateWriter.appendFollowUpEvent(
122:             command.getKey(), UserTaskIntent.CORRECTED, intermediateUserTaskRecord);
123:       }
124:     }
125: 
126:     findNextTaskListener(listenerEventType, userTaskElement, userTaskElementInstance)
