176:       commandProcessor
177:           .validateCommand(command)
178:           // Create a modifiable copy of the persisted user task record, as `onCommand` may
179:           // apply the changed attributes from the command on top of persisted instance.
180:           .map(UserTaskRecord::copy)
181:           .thenDo(persistedRecord -> commandProcessor.onCommand(command, persistedRecord))
182:           .ifRightOrLeft(
183:               persistedRecord ->
184:                   finalizeCommandOrCreateTaskListenerJob(
185:                       commandProcessor, command, persistedRecord, intentToWrite),
186:               rejection -> handleCommandRejection(command, rejection));
