324:   private ZeebeTaskListenerEventType mapIntentToEventType(final UserTaskIntent intentToWrite) {
325:     return switch (intentToWrite) {
326:       case CREATE -> ZeebeTaskListenerEventType.creating;
327:       case ASSIGN, CLAIM -> ZeebeTaskListenerEventType.assigning;
328:       case UPDATE -> ZeebeTaskListenerEventType.updating;
329:       case COMPLETE -> ZeebeTaskListenerEventType.completing;
330:       case CANCEL -> ZeebeTaskListenerEventType.canceling;
331:       default -> throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(
332:           intentToWrite));
333:     };
