338:     return switch (lifecycleState) {
339:       case CREATING -> ZeebeTaskListenerEventType.creating;
340:       case ASSIGNING, CLAIMING -> ZeebeTaskListenerEventType.assigning;
341:       case UPDATING -> ZeebeTaskListenerEventType.updating;
342:       case COMPLETING -> ZeebeTaskListenerEventType.completing;
343:       case CANCELING -> ZeebeTaskListenerEventType.canceling;
344:       default -> throw new IllegalArgumentException(
345:           "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
346:     };
347:   }
