350:     return switch (intentToWrite) {
351:       case COMPLETION_DENIED -> UserTaskIntent.COMPLETE;
352:       case ASSIGNMENT_DENIED -> UserTaskIntent.ASSIGN;
353:       case UPDATE_DENIED -> UserTaskIntent.UPDATE;
354:       default -> throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(
355:           intentToWrite));
