360:       final UserTaskIntent intent, final long userTaskKey, final String deniedReason) {
361:     return switch (intent) {
362:       case COMPLETION_DENIED -> USER_TASK_COMPLETION_REJECTION.formatted(userTaskKey, deniedReason);
363:       case ASSIGNMENT_DENIED -> USER_TASK_ASSIGNMENT_REJECTION.formatted(userTaskKey, deniedReason);
364:       case UPDATE_DENIED -> USER_TASK_UPDATE_REJECTION.formatted(userTaskKey, deniedReason);
365:       default ->
366:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
367:     };
