378:           case UPDATING -> UserTaskIntent.UPDATE;
379:           case COMPLETING -> UserTaskIntent.COMPLETE;
380:           case CANCELING -> UserTaskIntent.CANCEL;
381:           default -> throw new IllegalArgumentException(
382:               "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
