41: 
42:   private final SearchClientsProxy searchClientsProxy;
43:   private final BatchOperationMetrics metrics;
44: 
45:   /**
46:    * The size of a page when fetching entities. This is the maximum number of items that can be
47:    * fetched in a single query and is limited by ElasticSearch.
48:    */
49:   private final int queryPageSize;
50: 
51:   /**
52:    * The maximum number of keys that can be passed in a single IN clause in a query. This is limited
53:    * to 1000 because the Oracle DB supports a maximum of 1000 elements in an IN clause.
54:    */
55:   private final int inClauseSize;
