67:   /**
68:    * Fetches the process instance items for the given partitionId based on the provided filter. The
69:    * items are fetched sequentially in pages. Depending on the overall size of the result, this can
70:    * cause multiple queries to the secondary database.
71:    *
72:    * @param filter the filter to use
73:    * @param authentication the authentication to use
74:    * @param shouldAbort if the process should be aborted
75:    * @return a set of all found process instance items
76:    */
77:   public Set<Item> fetchProcessInstanceItems(
78:       final int partitionId,
79:       final ProcessInstanceFilter filter,
80:       final Authentication authentication,
81:       final Supplier<Boolean> shouldAbort) {
82:     final var processInstanceFilter = filter.toBuilder().partitionId(partitionId).build();
83: 
84:     LOG.debug(
85:         "Fetching process instance items for partition {} with filter: {}",
86:         partitionId,
87:         processInstanceFilter);
