139:   private <F extends FilterBase> Set<Item> fetchEntityItems(
140:       final ItemPageFetcher<F> itemPageFetcher,
141:       final F filter,
142:       final Authentication authentication,
143:       final Supplier<Boolean> shouldAbort) {
144:     final var items = new LinkedHashSet<Item>();
145: 
146:     Object[] searchAfter = null;
147:     while (true) {
148:       // Check if the batch operation is still present, could be canceled in the meantime
149:       if (shouldAbort.get()) {
150:         LOG.warn("Batch operation is no longer active, stopping query.");
151:         return Set.of();
152:       }
153: 
154:       metrics.recordQueryAgainstSecondaryDatabase();
155: 
156:       final var result = itemPageFetcher.fetchItems(filter, searchAfter, authentication);
157:       items.addAll(result.items);
158:       searchAfter = result.lastSortValues();
159: 
160:       // the result.total count can be incorrect when using elasticsearch and could be capped at
161:       // 10_000. If the result.total is smaller than the queryPageSize, we can assume that we have
