25: public class BatchOperationMetrics {
26: 
27:   private static final String ORGANIZATION_ID =
28:       System.getenv().getOrDefault("CAMUNDA_CLOUD_ORGANIZATION_ID", "null");
29: 
30:   final MeterRegistry registry;
31:   final int partitionId;
32: 
33:   private final Map<Tuple<BatchOperationAction, BatchOperationType>, Counter> executedActions =
34:       new ConcurrentHashMap<>();
35:   private final Map<Tuple<BatchOperationLatency, Long>, ResourceSample> latency =
36:       new ConcurrentHashMap<>();
37:   private Counter queryCounter;
38: 
39:   public BatchOperationMetrics(final MeterRegistry registry, final int partitionId) {
40:     this.registry = Objects.requireNonNull(registry, "must specify a registry");
41:     this.partitionId = partitionId;
42:   }
43: 
44:   public void recordCreated(final BatchOperationType batchOperationType) {
45:     batchOperationEvent(BatchOperationAction.CREATED, batchOperationType);
46:   }
47: 
48:   public void recordStarted(final BatchOperationType batchOperationType) {
49:     batchOperationEvent(BatchOperationAction.STARTED, batchOperationType);
50:   }
51: 
52:   public void recordFailed(final BatchOperationType batchOperationType) {
53:     batchOperationEvent(BatchOperationAction.FAILED, batchOperationType);
54:   }
55: 
56:   public void recordChunkCreated(final BatchOperationType batchOperationType) {
57:     batchOperationEvent(BatchOperationAction.CHUNK_CREATED, batchOperationType);
58:   }
59: 
60:   public void recordExecuted(final BatchOperationType batchOperationType) {
61:     batchOperationEvent(BatchOperationAction.EXECUTED, batchOperationType);
62:   }
63: 
64:   public void recordCancelled(final BatchOperationType batchOperationType) {
65:     batchOperationEvent(BatchOperationAction.CANCELLED, batchOperationType);
66:   }
67: 
68:   public void recordSuspended(final BatchOperationType batchOperationType) {
69:     batchOperationEvent(BatchOperationAction.SUSPENDED, batchOperationType);
70:   }
71: 
72:   public void recordResumed(final BatchOperationType batchOperationType) {
73:     batchOperationEvent(BatchOperationAction.RESUMED, batchOperationType);
74:   }
75: 
76:   public void recordCompleted(final BatchOperationType batchOperationType) {
77:     batchOperationEvent(BatchOperationAction.COMPLETED, batchOperationType);
78:   }
79: 
80:   public void startTotalLatencyMeasure(
81:       final Long batchOperationKey, final BatchOperationType batchOperationType) {
82:     createLatency(BatchOperationLatency.TOTAL_LATENCY, batchOperationKey, batchOperationType);
83:   }
84: 
85:   public void stopTotalLatencyMeasure(final Long batchOperationKey) {
86:     closeAndRemoveLatency(BatchOperationLatency.TOTAL_LATENCY, batchOperationKey);
87:   }
88: 
89:   public ResourceSample startTotalQueryLatencyMeasure(
90:       final Long batchOperationKey, final BatchOperationType batchOperationType) {
91:     return createLatency(
92:         BatchOperationLatency.TOTAL_QUERY_LATENCY, batchOperationKey, batchOperationType);
93:   }
94: 
95:   public void stopQueryLatencyMeasure(final Long batchOperationKey) {
96:     closeAndRemoveLatency(BatchOperationLatency.TOTAL_QUERY_LATENCY, batchOperationKey);
97:   }
98: 
99:   public void startTotalExecutionLatencyMeasure(
100:       final Long batchOperationKey, final BatchOperationType batchOperationType) {
101:     createLatency(
102:         BatchOperationLatency.TOTAL_EXECUTION_LATENCY, batchOperationKey, batchOperationType);
103:   }
104: 
105:   public void stopTotalExecutionLatencyMeasure(final Long batchOperationKey) {
106:     closeAndRemoveLatency(BatchOperationLatency.TOTAL_EXECUTION_LATENCY, batchOperationKey);
107:   }
108: 
109:   /**
110:    * Measures the time from the creation of the first execution command until the first execution in
111:    * the processor
112:    *
113:    * @param batchOperationKey
114:    * @param batchOperationType
115:    */
116:   public void startStartExecuteLatencyMeasure(
117:       final Long batchOperationKey, final BatchOperationType batchOperationType) {
118:     createLatency(
119:         BatchOperationLatency.START_EXECUTE_LATENCY, batchOperationKey, batchOperationType);
120:   }
121: 
122:   public void stopStartExecuteLatencyMeasure(final Long batchOperationKey) {
123:     closeAndRemoveLatency(BatchOperationLatency.START_EXECUTE_LATENCY, batchOperationKey);
124:   }
125: 
126:   public void startExecuteCycleLatencyMeasure(
127:       final Long batchOperationKey, final BatchOperationType batchOperationType) {
128:     createLatency(
129:         BatchOperationLatency.EXECUTE_CYCLE_LATENCY, batchOperationKey, batchOperationType);
130:   }
131: 
132:   public void stopExecuteCycleLatencyMeasure(final Long batchOperationKey) {
133:     closeAndRemoveLatency(BatchOperationLatency.EXECUTE_CYCLE_LATENCY, batchOperationKey);
134:   }
135: 
136:   /**
137:    * Records a query against the secondary database, which is used for batch operations. This metric
138:    * is used to track the number of queries made against the secondary database.
139:    *
140:    * <p>Since in the scheduler we have no batch operation type, we cannot use the executedActions
141:    * map
142:    */
143:   public synchronized void recordQueryAgainstSecondaryDatabase() {
144:     if (queryCounter == null) {
145:       final var meterDoc = BatchOperationMetricsDoc.EXECUTED_QUERIES;
146:       queryCounter =
147:           Counter.builder(meterDoc.getName())
148:               .description(meterDoc.getDescription())
149:               .tag(PartitionKeyNames.PARTITION.asString(), String.valueOf(partitionId))
150:               .tag(BatchOperationKeyNames.ORGANIZATION_ID.asString(), ORGANIZATION_ID)
151:               .register(registry);
152:     }
153: 
154:     queryCounter.increment();
155:   }
156: 
157:   public void recordItemsPerPartition(
158:       final int itemsAmount,
159:       final long batchOperationKey,
160:       final BatchOperationType batchOperationType) {
161:     final var meterDoc = BatchOperationMetricsDoc.ITEMS_PER_PARTITION;
162:     DistributionSummary.builder(meterDoc.getName())
163:         .description(meterDoc.getDescription())
164:         .tag(
165:             BatchOperationKeyNames.BATCH_OPERATION_KEY.asString(),
166:             String.valueOf(batchOperationKey))
167:         .tag(PartitionKeyNames.PARTITION.asString(), String.valueOf(partitionId))
168:         .tag(BatchOperationKeyNames.BATCH_OPERATION_TYPE.asString(), batchOperationType.toString())
169:         .tag(BatchOperationKeyNames.ORGANIZATION_ID.asString(), ORGANIZATION_ID)
170:         .serviceLevelObjectives(
171:             1,
172:             2,
173:             5,
174:             10,
175:             20,
176:             50,
177:             100,
178:             200,
179:             500,
180:             1_000,
181:             2_000,
182:             5_000,
183:             10_000,
184:             20_000,
185:             50_000,
186:             100_000,
187:             500_000,
188:             1_000_000,
189:             2_000_000,
190:             5_000_000,
191:             10_000_000)
192:         .register(registry)
193:         .record(itemsAmount);
194:   }
195: 
196:   private void batchOperationEvent(
197:       final BatchOperationAction action, final BatchOperationType batchOperationType) {
198:     executedActions
199:         .computeIfAbsent(
200:             Tuple.of(action, batchOperationType),
201:             (key) -> registerBatchOperationEventCounter(action, batchOperationType))
202:         .increment();
203:   }
204: 
205:   private Counter registerBatchOperationEventCounter(
206:       final BatchOperationAction batchOperationAction,
207:       final BatchOperationType batchOperationType) {
208:     final var meterDoc = BatchOperationMetricsDoc.EXECUTED_LIFECYCLE_EVENTS;
209:     return Counter.builder(meterDoc.getName())
210:         .description(meterDoc.getDescription())
211:         .tag(BatchOperationKeyNames.BATCH_OPERATION_TYPE.asString(), batchOperationType.toString())
212:         .tag(BatchOperationKeyNames.ACTION.asString(), batchOperationAction.toString())
213:         .tag(PartitionKeyNames.PARTITION.asString(), String.valueOf(partitionId))
214:         .tag(BatchOperationKeyNames.ORGANIZATION_ID.asString(), ORGANIZATION_ID)
215:         .register(registry);
216:   }
217: 
218:   /**
219:    * Creates a latency measurement for the given latency type and batch operation key. If the
220:    * latency measurement already exists, it returns the existing one.
221:    *
222:    * @param latencyType the type of latency to create
223:    * @param batchOperationKey the key of the batch operation
224:    * @param batchOperationType the type of batch operation
225:    * @return the created or existing ResourceSample for the latency
226:    */
227:   private ResourceSample createLatency(
228:       final BatchOperationLatency latencyType,
229:       final Long batchOperationKey,
230:       final BatchOperationType batchOperationType) {
231:     return latency.computeIfAbsent(
232:         createLatencyKey(latencyType, batchOperationKey),
233:         (key) -> registerBatchOperationLatency(batchOperationKey, latencyType, batchOperationType));
234:   }
235: 
236:   /**
237:    * Closes the latency measurement and removes it from the map. If the latency measurement does not
238:    * exist, it does nothing.
239:    *
240:    * @param latency the latency type to close
241:    * @param batchOperationKey the key of the batch operation
242:    */
243:   private void closeAndRemoveLatency(
244:       final BatchOperationLatency latency, final Long batchOperationKey) {
245:     final var key = createLatencyKey(latency, batchOperationKey);
246:     if (this.latency.containsKey(key)) {
247:       this.latency.get(key).close();
248:       this.latency.remove(key);
249:     }
250:   }
251: 
252:   private static Tuple<BatchOperationLatency, Long> createLatencyKey(
253:       final BatchOperationLatency latency, final Long batchOperationKey) {
254:     return Tuple.of(latency, batchOperationKey);
255:   }
256: 
257:   private ResourceSample registerBatchOperationLatency(
258:       final Long batchOperationKey,
259:       final BatchOperationLatency batchOperationLatency,
260:       final BatchOperationType batchOperationType) {
261:     final var meterDoc = BatchOperationMetricsDoc.BATCH_OPERATION_LATENCY;
262:     return Timer.resource(registry, meterDoc.getName())
263:         .description(meterDoc.getDescription())
264:         .tag(
265:             BatchOperationKeyNames.BATCH_OPERATION_KEY.asString(),
266:             String.valueOf(batchOperationKey))
267:         .tag(PartitionKeyNames.PARTITION.asString(), String.valueOf(partitionId))
268:         .tag(BatchOperationKeyNames.LATENCY.asString(), batchOperationLatency.toString())
269:         .tag(BatchOperationKeyNames.BATCH_OPERATION_TYPE.asString(), batchOperationType.toString())
270:         .tag(BatchOperationKeyNames.ORGANIZATION_ID.asString(), ORGANIZATION_ID);
271:   }
272: }
